  BasicBlock b;
  BBQ bbq=new BBQ();
  Code_attribute c=method.locate_code_attribute();
  if (c == null)   return;
  try {
    {
      BasicBlock bb=cfg;
      while (bb != null) {
        bb.done=true;
        bb=bb.next;
      }
    }
    bbq.push(cfg);
